import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def get_prime_power_info(N):
    """
    Checks if N is a perfect power of a single prime p^k with k >= 2.
    Returns (p, k) if true, otherwise (None, None).
    """
    if N <= 3:
        return (None, None)

    # Find prime factorization
    factors = {}
    d = 2
    temp = N
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    # Check if there is exactly one prime factor
    if len(factors) != 1:
        return (None, None)

    p = list(factors.keys())[0]
    k = list(factors.values())[0]

    # Check the exponent condition
    if k >= 2:
        return (p, k)
    else:
        return (None, None)

m_results = []
n_results = []
p_results = []

for m in range(1, 6):
    for n in range(1, 6):
        A = m**2 + n
        B = m + n**2

        p1, k1 = get_prime_power_info(A)
        p2, k2 = get_prime_power_info(B)

        # Check if both are prime powers and if the primes match
        if p1 is not None and p2 is not None and p1 == p2:
            p = p1
            m_results.append(m)
            n_results.append(n)
            p_results.append(p)

print("Found triples (m, n, p):")
for i in range(len(m_results)):
    print(f"({m_results[i]}, {n_results[i]}, {p_results[i]})")

print("\nList of (m, n, p) tuples:")
tuples = list(zip(m_results, n_results, p_results))
